import sys


def is_valid(line: str) -> bool:
    matching = {")": "(", "]": "[", "}": "{"}
    stack = []

    for bracket in line:
        if bracket in "([{":
            stack.append(bracket)
        elif not stack or stack.pop() != matching[bracket]:
            return False

    return not stack


def main() -> None:
    first_line = sys.stdin.buffer.readline()
    if not first_line:
        return

    count = int(first_line)
    results = []
    for _ in range(count):
        line = sys.stdin.buffer.readline().rstrip(b"\r\n").decode("ascii")
        results.append("valid" if is_valid(line) else "invalid")

    if results:
        sys.stdout.write("\n".join(results) + "\n")


if __name__ == "__main__":
    main()

