import sys


def main() -> None:
    lines = sys.stdin.buffer
    first = lines.readline()
    if not first:
        return

    count = int(first)
    numbers = [int(lines.readline()) for _ in range(count)]

    parts: list[str] = []
    index = 0
    while index < count:
        end = index
